// LabFlow — check a booking request with a list of rules.
// A teammate's first version: it runs, but the function types are guesses. Lab 3: type it properly.
import { parseTime } from './time.ts';
import { OPEN, CLOSE, STEP, MAX_MINUTES } from './booking.ts';
import type { BookingInput } from './booking.ts';

export type Problem = { code: string; message: string };
export type Rule = Function;

// One "HH:MM" -> minutes, or a list of them -> a list of minutes.
export function toMinutes(value: string | string[]): number | number[] {
  return typeof value === 'string' ? parseTime(value) : value.map((t) => parseTime(t));
}

export const onGrid = ({ start, end }: BookingInput) =>
  parseTime(start) % STEP !== 0 || parseTime(end) % STEP !== 0
    ? { code: 'OFF_GRID', message: 'Start and end must be on the 30-minute grid' }
    : null;

export const endAfterStart = ({ start, end }: BookingInput) =>
  parseTime(end) <= parseTime(start) ? { code: 'END_BEFORE_START', message: 'End must be after start' } : null;

export const withinHours = ({ start, end }: BookingInput) =>
  parseTime(start) < OPEN || parseTime(end) > CLOSE
    ? { code: 'OUTSIDE_HOURS', message: 'Labs are open 07:00–21:00' }
    : null;

export const notTooLong = ({ start, end }: BookingInput) =>
  parseTime(end) - parseTime(start) > MAX_MINUTES ? { code: 'TOO_LONG', message: 'At most 4 hours' } : null;

export function maxSeats(limit) {
  return ({ seats }: BookingInput) => (seats >= limit ? { code: 'TOO_MANY_SEATS', message: 'At most ' + limit + ' seats' } : null);
}

export const RULES: Rule[] = [onGrid, endAfterStart, withinHours, notTooLong, maxSeats(40)];

export function validate(input: BookingInput, rules: Rule[], onProblem?: Function): Problem[] {
  for (const rule of rules) {
    const problem = rule(input);
    if (problem !== null) {
      if (onProblem) onProblem(problem);
      return [problem];
    }
  }
  return [];
}

export function totalMinutes(...ranges) {
  let total = 0;
  for (const [start, end] of ranges) total += end - start;
  return total;
}

export function createValidator(rules: Rule[]) {
  return {
    rules,
    run(input: BookingInput) {
      return validate(input, this.rules);
    },
  };
}

// Convert between "HH:MM" and minutes since 00:00.
export function parseTime(text: string): number {
  const m = /^([0-9]{2}):([0-9]{2})$/.exec(text);
  if (!m) throw new TypeError('Invalid time "' + text + '", expected HH:MM');
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) throw new RangeError('Time out of range: ' + text);
  return h * 60 + min;
}

export function formatTime(minutes: number): string {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

import { parseTime } from './time.ts';

export const OPEN = 7 * 60;          // 07:00
export const CLOSE = 21 * 60;        // 21:00
export const STEP = 30;              // BR-04: 30-minute grid
export const MAX_MINUTES = 240;      // Lite-1: at most 4 hours
export const MAX_DAYS_AHEAD = 14;    // BR-05: at most 14 days ahead
export const APPROVAL_SEATS = 30;    // BR-06: more than 30 seats needs approval

export type Role = 'STUDENT' | 'LECTURER' | 'ADMIN';
export type SlotCode = 'OFF_GRID' | 'END_BEFORE_START' | 'OUTSIDE_HOURS' | 'TOO_LONG';
export type SlotResult = { ok: true; minutes: number } | { ok: false; code: SlotCode };

export type BookingInput = { lab: string; seats: number; role: Role; start: string; end: string };
export type Booking = {
  lab: string;
  start: string;
  end: string;
  minutes: number;
  status: 'PENDING' | 'CONFIRMED';
};

export function checkSlot(start: string, end: string): SlotResult {
  const s = parseTime(start);
  const e = parseTime(end);
  if (s % STEP !== 0 || e % STEP !== 0) return { ok: false, code: 'OFF_GRID' };
  if (e <= s) return { ok: false, code: 'END_BEFORE_START' };
  if (s < OPEN || e > CLOSE) return { ok: false, code: 'OUTSIDE_HOURS' };
  if (e - s > MAX_MINUTES) return { ok: false, code: 'TOO_LONG' };
  return { ok: true, minutes: e - s };
}

export function isWithinBookingWindow(daysAhead: number): boolean {
  return Number.isInteger(daysAhead) && daysAhead >= 0 && daysAhead <= MAX_DAYS_AHEAD;
}

export function needsApproval({ seats, role }: { seats: number; role: Role }): boolean {
  if (!Number.isInteger(seats) || seats < 1) {
    throw new RangeError('seats must be a positive integer, got ' + seats);
  }
  if (role === 'LECTURER' || role === 'ADMIN') return false;
  return seats > APPROVAL_SEATS;
}

export function createBooking({ lab, seats, role, start, end }: BookingInput): Booking {
  const slot = checkSlot(start, end);
  if (!slot.ok) throw new Error(slot.code);
  return {
    lab,
    start,
    end,
    minutes: slot.minutes,
    status: needsApproval({ seats, role }) ? 'PENDING' : 'CONFIRMED',
  };
}

// Share of opening hours already booked, added booking by booking (0..1).
export function usageRate(bookings: readonly { minutes: number }[]): number {
  let rate = 0;
  for (const b of bookings) rate += b.minutes / (CLOSE - OPEN);
  return rate;
}

// LabFlow — one lab's schedule for a day (Chapter 2, = Lab 2 reference solution).
import { parseTime, formatTime } from './time.ts';

// The one list of labs. `as const` keeps the exact strings, so the type below is derived from it, never copied.
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

// [start, end] in minutes since 00:00 — exactly two numbers, never changed in place.
export type TimeRange = readonly [start: number, end: number];

export type ScheduleEntry = {
  id: number;
  lab: LabCode;
  range: TimeRange;
  bookedBy: string;
  note: string | null;      // NULL in the database: the booker wrote no note ('' is a real, empty note)
  cancelledAt?: string;     // absent until the booking is cancelled
};

// A text from outside (a query string, a form) is checked at runtime before it is trusted to be a LabCode.
export function isLab(text: string): text is LabCode {
  return LABS.some((lab) => lab === text);
}

// "08:00-10:00" -> [480, 600]
export function toRange(text: string): TimeRange {
  const [from, to, extra] = text.split('-');
  if (from === undefined || to === undefined || extra !== undefined) {
    throw new TypeError('Invalid range "' + text + '", expected HH:MM-HH:MM');
  }
  return [parseTime(from), parseTime(to)];
}

export function findEntry(schedule: readonly ScheduleEntry[], id: number): ScheduleEntry | undefined {
  return schedule.find((e) => e.id === id);
}

export function noteOf(entry: ScheduleEntry): string {
  return entry.note ?? '(no note)';
}

// Earliest start of a lab today, ignoring cancelled bookings; null when the lab is free all day.
export function firstStart(schedule: readonly ScheduleEntry[], lab: LabCode): number | null {
  let best: number | null = null;
  for (const e of schedule) {
    if (e.lab !== lab || e.cancelledAt !== undefined) continue;
    if (best === null || e.range[0] < best) best = e.range[0];
  }
  return best;
}

// A sorted COPY: the caller's list keeps its order.
export function sortByStart(schedule: readonly ScheduleEntry[]): ScheduleEntry[] {
  return schedule.toSorted((a, b) => a.range[0] - b.range[0]);
}

// "BE-201 08:00–10:00 an.nv (cancelled 2026-11-02)"
export function labelOf(entry: ScheduleEntry): string {
  const [start, end] = entry.range;
  const state = entry.cancelledAt === undefined ? '' : ' (cancelled ' + entry.cancelledAt.slice(0, 10) + ')';
  return entry.lab + ' ' + formatTime(start) + '–' + formatTime(end) + ' ' + entry.bookedBy + state;
}

